const name="World",items=["apple","banana","cherry"],simple=`Hello, ${name}!`;print(simple);const multiline=`Line one\nLine two with ${items.length} items\nLine three`;print(multiline);const nested="outer-inner-2-end";print(nested);const list=`Items: ${items.map(function(n,e){return`${e}:${n}`}).join(", ")}`;function computeExpr(n,e){return`${n} + ${e} = ${n+e}, ${n} * ${e} = ${n*e}`}print(list),print(computeExpr(3,4));